preConditionHook:
// GRIMES'S NAMED "TRADING COMPLEX PULLBACKS" TEMPLATE (G06-32), carried as
// the book states it and with its parts INLINED. A complex pullback is a
// complete ABCD structure in itself -- two distinct countertrend legs separated
// by a with-trend retracement -- and it is very common in mature trends, where
// a climax blocks the simple Pullback template but permits this one. That is
// the one place the two templates are not interchangeable.
//
// TWO PARTS, BOTH ORs:
//   1. THE STRUCTURE: the pullback's SECOND leg runs past the first leg's
//      extreme (ComplexPullbackSecondLegBeyondFirst = the on-disk
//      SecondLegExceedsFirstLegExtreme, G06-27) **OR** the hidden cue -- "one
//      or two with-trend candles in the middle of what otherwise looks like a
//      simple pullback" (HiddenComplexPullbackBodyCount = OppositeBodyCountInWindow
//      with its minOpposite amendment, G06-28).
//   2. THE TRIGGER, the SAME pair the simple Pullback template uses:
//      break-and-recover of the pullback's own extreme (LevelBreakAndRecover,
//      G06-03) **OR** a bounce off it (SupportResistanceBounceEntry, G06-04, a
//      merge working name resolved through the mined candidate to the on-disk
//      LowTouchesRecentRangeLow at lag 0).
// TWO ORs ANDed IS WHY THE TEMPLATE IS ONE FILE -- entry panes AND, so neither
// OR is reachable, let alone their conjunction.
//
// THE HIDDEN CUE IS A BAND ON THE AGAINST-TREND BODY COUNT, which is what the
// merge's minOpposite amendment buys: on the long side the pullback's own bars
// are BEAR-bodied, so "one or two with-trend candles inside it" is
// "bearBodies between minOpposite and maxOpposite over bodyWindow bars" --
// at the defaults, 3 or 4 bear bodies in a 5-bar window, leaving one or two
// bull ones. Counting the WITH-trend bodies directly would need the short
// side's quantity on the long side, which no placement can borrow.
//
// THE LEG STRUCTURE IS THE CORPUS'S SETTLED LEG COUNTER, inlined verbatim from
// SecondLegExceedsFirstLegExtreme: CROSS-BAR STATE that resets when the closing
// price clears the shifted resetLookback window extreme, counts a leg on each
// bar that makes a higher high after a lower low than the last signal, caps the
// count at 4, and fires once the second leg's lowest low has run past the first
// leg's. The state locals persist across bars and are DELIBERATELY not reset at
// the top of the hook, which is what makes them state.
//
// THE PULLBACK'S SUPPORT IS SHARED STATE between the two triggers, and the two
// SHIFTS ARE KEPT APART exactly as in the Pullback template: break-and-recover
// reads the window ending TWO bars ago so the breaking bar's own low cannot
// define the level it broke, the bounce reads the window ending ONE bar ago.
//
// NOT `Pullback`: no setup-leg or quiet-pullback test at all (Grimes drops both
// for the complex form) and a different structural precondition, so different
// bars. The target is the AB=CD leg-equality move, the on-disk
// LegOneEqualsLegTwoTarget, and the stop (G06-31) belongs to the exits pass.
// Grimes pairs this with NoClimaxBarInWindow NEGATED in its own pane.
//
// SHIFT TEST: window extremes, body colours and counts only; the one tolerance
// is an ATR fraction (decision 7).
//
// WFSafe_AvgTrueRange is MultiWalk's ROLLING accumulator, a different function
// from the built-in it resembles.
//
// Deepest bar touched: max(resetLookback, pullbackLookback + 1, bodyWindow - 1,
// atrLength + 1).
//
// THE C++ TWIN WRITES OUT BY HAND what the EL twin says with built-ins.
// Highest/Lowest bottom out in Extremes(), EL SOURCE, so each window is a scan
// SEEDED ON THE WINDOW'S FIRST BAR and continued with a STRICT comparison under
// the EL relational tolerance (el_gt / el_lt). CountIF becomes a counting loop
// over the CURRENT-INCLUSIVE window, bars 0..bodyWindow-1, which is what that
// word does.
//
// Every scratch value is a localVariables entry rather than a hook-scope
// declaration, so the hooks survive a double placement; loop counters are
// block-scoped. THE LEG-COUNTER STATE IS NOT RESET at the top of the hook --
// that is the point of it -- and a double placement gets its own copy because
// each placement gets its own locals.
if (atrLenState != (int)atrLength) {
    atrSum = 0.0;
    for (int aa = 0; aa < (int)atrLength; ++aa) {
        hiV = high[aa] > close[aa + 1] ? high[aa] : close[aa + 1];
        loV = low[aa] < close[aa + 1] ? low[aa] : close[aa + 1];
        atrSum += hiV - loV;
    }
    atrLenState = (int)atrLength;
} else {
    outIdx = (int)atrLength;
    hiV = high[0] > close[1] ? high[0] : close[1];
    loV = low[0] < close[1] ? low[0] : close[1];
    hiO = high[outIdx] > close[outIdx + 1] ? high[outIdx] : close[outIdx + 1];
    loO = low[outIdx] < close[outIdx + 1] ? low[outIdx] : close[outIdx + 1];
    atrSum += hiV - loV;
    atrSum -= hiO - loO;
}
atrValue = atrSum / (int)atrLength;
priorHigh = high[1];
priorLow = low[1];
for (int i = 2; i <= (int)resetLookback; ++i) {
    if (el_gt(high[i], priorHigh)) priorHigh = high[i];
    if (el_lt(low[i], priorLow)) priorLow = low[i];
}
if (el_gt(close[0], priorHigh)) {
    highCount = 0;
} else {
    if (el_lt(low[0], minLowSince)) minLowSince = low[0];
    if (el_gt(high[0], high[1]) && (highCount == 0 || el_lt(minLowSince, signalLow))) {
        highCount = highCount + 1;
        if (highCount > 4) highCount = 4;
        signalLow = low[0];
        minLowSince = low[0];
        if (highCount == 1) firstLegLow = low[0];
    }
}
if (el_lt(close[0], priorLow)) {
    lowCount = 0;
} else {
    if (el_gt(high[0], maxHighSince)) maxHighSince = high[0];
    if (el_lt(low[0], low[1]) && (lowCount == 0 || el_gt(maxHighSince, signalHigh))) {
        lowCount = lowCount + 1;
        if (lowCount > 4) lowCount = 4;
        signalHigh = high[0];
        maxHighSince = high[0];
        if (lowCount == 1) firstLegHigh = high[0];
    }
}
twoLegUp = el_ge((double)highCount, 2.0) && el_lt(minLowSince, firstLegLow);
twoLegDn = el_ge((double)lowCount, 2.0) && el_gt(maxHighSince, firstLegHigh);
bearBodies = 0;
bullBodies = 0;
for (int kk = 0; kk <= (int)bodyWindow - 1; ++kk) {
    if (el_lt(close[kk], open[kk])) bearBodies = bearBodies + 1;
    if (el_gt(close[kk], open[kk])) bullBodies = bullBodies + 1;
}
hiddenUp = el_ge((double)bearBodies, minOpposite) && el_le((double)bearBodies, maxOpposite);
hiddenDn = el_ge((double)bullBodies, minOpposite) && el_le((double)bullBodies, maxOpposite);
supp1 = low[1];
res1 = high[1];
for (int i = 2; i <= (int)pullbackLookback; ++i) {
    if (el_lt(low[i], supp1)) supp1 = low[i];
    if (el_gt(high[i], res1)) res1 = high[i];
}
supp2 = low[2];
res2 = high[2];
for (int i = 3; i <= (int)pullbackLookback + 1; ++i) {
    if (el_lt(low[i], supp2)) supp2 = low[i];
    if (el_gt(high[i], res2)) res2 = high[i];
}
trigUp = (el_lt(low[1], supp2) && el_gt(close[0], supp2)) || el_le(low[0], supp1 + tolAtr * atrValue);
trigDn = (el_gt(high[1], res2) && el_lt(close[0], res2)) || el_ge(high[0], res1 - tolAtr * atrValue);
